import React from "react";
import { GatsbyImage, getImage, type IGatsbyImageData } from "gatsby-plugin-image";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { format, isValid, parseISO } from "date-fns";
import { es, fr, enUS } from "date-fns/locale";
import images from "../images";
import SEO from "../components/seo";
import AppLink from "./AppLink";
import EntityTrustPanel from "./EntityTrustPanel";
import type { Company, Post as BlogPost } from "../interfaces";
import {
  buildAbsoluteUrl,
  buildBreadcrumbListSchema,
  buildPersonSchema,
  localizeSitePath,
} from "../utils/structuredData";
import {
  getCategoryServicePath,
  getRelatedPosts,
} from "../utils/postTaxonomy";
import { trackCtaClick } from "../utils/analytics";
import {
  getPrimaryCaseStudyPathForServicePath,
  getServiceKeyFromPath,
} from "../utils/journeyLinks";

type FaqItem = { q: string; a: string };
type ProfilePoint = { item: string };
type BlogLabels = {
  breadcrumb: string;
  home: string;
  blogHub: string;
  tldr: string;
  faq: string;
  contact: string;
  web: string;
  analytics: string;
  seoService: string;
  by: string;
  published: string;
  updated: string;
  reviewedBy: string;
  authorCta: string;
  aiSearch: string;
};

interface PostProps {
  date: string;
  updatedDate?: string;
  slug: string;
  data: Company;
  allPosts?: BlogPost[];
  imageNodes?: Array<{
    name: string;
    childImageSharp?: {
      gatsbyImageData: IGatsbyImageData;
    } | null;
  }>;
}

const useBlogPostData = ({
  date,
  updatedDate,
  slug,
  data,
  allPosts = [],
  imageNodes = [],
}: PostProps) => {
  const { t, i18n } = useTranslation(["blog", "index"]);
  const defaultLanguage = "fr";

  const getLocale = (language: string) => {
    switch (language) {
      case "es":
        return es;
      case "fr":
        return fr;
      default:
        return enUS;
    }
  };

  const localizedPath = localizeSitePath(
    `/blog/${slug}/`,
    i18n.language,
    defaultLanguage
  );
  const localizedBlogHubPath = localizeSitePath(
    "/blog/",
    i18n.language,
    defaultLanguage
  );

  const urls = {
    about: "/about/",
    aiSearch: "/services/ai-search-optimization/",
    seo: "/services/seo/",
    web: "/services/web-design-development/",
    portfolio: "/portfolio/",
    contact: "/contact/",
  };
  const geoClusterSlugs = new Set([
    "what_is_geo_ai_search_optimization",
    "seo_vs_geo_vs_aeo",
    "service_pages_citable_ai_search",
    "structured_data_for_ai_search",
    "proof_results_clear_claims_ai_search",
    "how_to_measure_geo_visibility",
  ]);

  const metaTitle =
    (t(`blog.${slug}-metaTitle`) as string) ||
    (t(`blog.${slug}-title`) as string) ||
    "";

  const h1Title = (t(`blog.${slug}-title`) as string) || "";
  const metaDescription = (t(`blog.${slug}-description`) as string) || "";
  const excerptHtml = (t(`blog.${slug}-excerpt`) as string) || "";
  const currentPost = allPosts.find((post) => post.slug === slug);

  const tldrRaw = t(`blog.${slug}-tldr`, { returnObjects: true }) as unknown;
  const faqsRaw = t(`blog.${slug}-faqs`, { returnObjects: true }) as unknown;

  const tldr = Array.isArray(tldrRaw) ? (tldrRaw as string[]) : [];
  const faqs = Array.isArray(faqsRaw) ? (faqsRaw as FaqItem[]) : [];

  const formatDate = (value: string) => {
    const parsed = parseISO(value);
    if (!isValid(parsed)) {
      return value;
    }

    return format(parsed, "MMMM dd, yyyy", {
      locale: getLocale(i18n.language),
    });
  };

  const formattedDate = formatDate(date);
  const formattedUpdatedDate = updatedDate ? formatDate(updatedDate) : formattedDate;

  const postImage = images[slug as keyof typeof images] ?? images.bg_workflow;

  // FAQ schema
  const faqSchema =
    faqs.length > 0
      ? {
          "@context": "https://schema.org",
          "@type": "FAQPage",
          mainEntity: faqs.map((item) => ({
            "@type": "Question",
            name: item.q,
            acceptedAnswer: { "@type": "Answer", text: item.a },
          })),
        }
      : null;

  // OG image absoluto (recomendado). Si postImage.src ya es absoluto, úsalo tal cual.
  const ogImage =
    postImage?.src && /^https?:\/\//i.test(postImage.src)
      ? postImage.src
      : postImage?.src
        ? `${data.url}${postImage.src.startsWith("/") ? postImage.src : `/${postImage.src}`}`
        : undefined;

  const siteUrl = (data?.url || "").replace(/\/+$/, "");
  const canonicalUrl = siteUrl ? `${siteUrl}${localizedPath}` : undefined;
  const personSchema = data.founder?.name
    ? buildPersonSchema({
        siteUrl,
        profilePath: localizeSitePath("/about/", i18n.language, defaultLanguage),
        name: data.founder.name,
        jobTitle: t("about.profile.role", { ns: "index" }) as string,
        description: t("about.profile.summary", { ns: "index" }) as string,
        inLanguage: i18n.language,
        sameAs: data.founder.sameAs,
        worksForName: data.companyName || "Code Crafted Studios",
      })
    : undefined;

  const personId = data.founder?.name && siteUrl ? `${siteUrl}/#person` : undefined;

  const labels = t("blog.uiLabels", {
    returnObjects: true,
  }) as BlogLabels;
  const authorSummary = t("about.profile.summary", { ns: "index" }) as string;
  const authorRole = t("about.profile.role", { ns: "index" }) as string;
  const authorPointsRaw = t("about.profile.points", {
    ns: "index",
    returnObjects: true,
  }) as unknown;
  const authorHighlights = Array.isArray(authorPointsRaw)
    ? (authorPointsRaw as ProfilePoint[]).map((point) => point.item).filter(Boolean)
    : [];
  const showAiSearchLink = geoClusterSlugs.has(slug);
  const currentCategoryLabel = currentPost?.category
    ? (t(`blog.taxonomy.categories.${currentPost.category}`, {
        defaultValue: currentPost.category,
      }) as string)
    : "";
  const currentSeriesLabel = currentPost?.series
    ? (t(`blog.taxonomy.series.${currentPost.series}`, {
        defaultValue: currentPost.series,
      }) as string)
    : "";
  const articleSection = [currentCategoryLabel, currentSeriesLabel]
    .filter(Boolean)
    .join(" / ");
  const articleKeywords = [
    ...(currentPost?.tags || []),
    currentCategoryLabel,
    currentSeriesLabel,
  ].filter(Boolean);
  const relatedServicePath = getCategoryServicePath(currentPost || {});
  const relatedServiceKey =
    relatedServicePath && relatedServicePath !== "/services/"
      ? getServiceKeyFromPath(relatedServicePath)
      : undefined;
  const relatedServiceUrl =
    siteUrl && relatedServicePath
      ? buildAbsoluteUrl(
          siteUrl,
          localizeSitePath(relatedServicePath, i18n.language, defaultLanguage)
        )
      : undefined;
  const relatedCaseStudyPath = getPrimaryCaseStudyPathForServicePath(
    relatedServicePath
  );
  const relatedServiceName = relatedServicePath.includes(
    "/services/ai-search-optimization/"
  )
    ? labels.aiSearch
    : relatedServicePath.includes("/services/analytics/")
      ? labels.analytics
      : relatedServicePath.includes("/services/seo/")
        ? labels.seoService
        : labels.web;
  const relatedServiceCta =
    relatedServiceKey === "seo"
      ? (t("blog.journey.serviceSeo") as string)
      : relatedServiceKey === "analytics"
        ? (t("blog.journey.serviceAnalytics") as string)
        : relatedServiceKey === "aiSearchOptimization"
          ? (t("blog.journey.serviceAiSearch") as string)
          : (t("blog.journey.serviceWeb") as string);
  const relatedCaseStudyCta =
    relatedServiceKey === "seo"
      ? (t("blog.journey.caseStudySeo") as string)
      : relatedServiceKey === "analytics"
        ? (t("blog.journey.caseStudyAnalytics") as string)
        : relatedServiceKey === "aiSearchOptimization"
          ? (t("blog.journey.caseStudyAiSearch") as string)
          : (t("blog.journey.caseStudyWeb") as string);
  const contactAuditCta = t("blog.journey.contactAudit") as string;
  const articleAbout = [
    currentCategoryLabel
      ? {
          "@type": "Thing",
          name: currentCategoryLabel,
        }
      : null,
    currentSeriesLabel
      ? {
          "@type": "Thing",
          name: currentSeriesLabel,
        }
      : null,
    relatedServiceUrl
      ? {
          "@type": "Service",
          name: relatedServiceName,
          url: relatedServiceUrl,
        }
      : null,
  ].filter(Boolean);
  const articleSchema = canonicalUrl
    ? {
        "@context": "https://schema.org",
        "@type": "BlogPosting",
        headline: metaTitle || h1Title,
        description: metaDescription,
        datePublished: new Date(date).toISOString(),
        dateModified: new Date(updatedDate || date).toISOString(),
        inLanguage: i18n.language,
        url: canonicalUrl,
        mainEntityOfPage: canonicalUrl,
        ...(ogImage ? { image: ogImage } : {}),
        ...(articleKeywords.length
          ? { keywords: articleKeywords.join(", ") }
          : {}),
        ...(articleSection ? { articleSection } : {}),
        isPartOf: {
          "@type": "CollectionPage",
          name: labels.blogHub,
          url: siteUrl ? buildAbsoluteUrl(siteUrl, localizedBlogHubPath) : undefined,
        },
        ...(articleAbout.length ? { about: articleAbout } : {}),
        author: personId
          ? {
              "@id": personId,
            }
          : {
              "@type": "Organization",
              name: data.companyName || "Code Crafted Studios",
              url: siteUrl || undefined,
            },
        ...(personId
          ? {
              reviewedBy: {
                "@id": personId,
              },
            }
          : {}),
        publisher: {
          "@type": "Organization",
          name: data.companyName || "Code Crafted Studios",
          url: siteUrl || undefined,
        },
      }
    : null;
  const breadcrumbSchema = canonicalUrl
    ? buildBreadcrumbListSchema(siteUrl, [
        {
          name: labels.home,
          path: localizeSitePath("/", i18n.language, defaultLanguage),
        },
        {
          name: labels.blogHub,
          path: localizedBlogHubPath,
        },
        {
          name: metaTitle || h1Title,
          path: localizedPath,
        },
      ])
    : undefined;
  const relatedPosts = currentPost ? getRelatedPosts(currentPost, allPosts) : [];
  const imageLookup = React.useMemo(
    () =>
      new Map(
        imageNodes
          .map((node) => {
            const image = node.childImageSharp?.gatsbyImageData
              ? getImage(node.childImageSharp.gatsbyImageData)
              : undefined;

            return image ? [node.name, image] : null;
          })
          .filter(
            (
              entry
            ): entry is [string, IGatsbyImageData] => Array.isArray(entry)
          )
      ),
    [imageNodes]
  );
  const optimizedPostImage = imageLookup.get(slug);

  return {
    articleSchema,
    authorSummary,
    authorRole,
    breadcrumbSchema,
    currentCategoryLabel,
    currentSeriesLabel,
    excerptHtml,
    faqSchema,
    faqs,
    formattedDate,
    formattedUpdatedDate,
    h1Title,
    labels,
    localizedPath,
    metaDescription,
    metaTitle,
    ogImage,
    optimizedPostImage,
    personSchema,
    postImage,
    relatedCaseStudyCta,
    relatedCaseStudyPath,
    relatedPosts,
    relatedServiceCta,
    relatedServicePath,
    showAiSearchLink,
    tldr,
    urls,
    imageLookup,
    authorHighlights,
    contactAuditCta,
  };
};

export const BlogHead: React.FC<PostProps> = (props) => {
  const {
    metaTitle,
    metaDescription,
    ogImage,
    localizedPath,
    articleSchema,
    breadcrumbSchema,
    faqSchema,
    personSchema,
  } = useBlogPostData(props);
  const additionalSchemas = [
    personSchema,
    articleSchema,
    breadcrumbSchema,
    faqSchema,
  ].filter(Boolean) as object[];

  return (
    <SEO
      data={props.data}
      title={metaTitle}
      description={metaDescription}
      image={ogImage}
      pathname={localizedPath}
      schemaType="Organization"
      additionalSchemas={additionalSchemas.length ? additionalSchemas : undefined}
    />
  );
};

const Post: React.FC<PostProps> = (props) => {
  const { t } = useTranslation("blog");
  const {
    authorRole,
    authorSummary,
    authorHighlights,
    currentCategoryLabel,
    currentSeriesLabel,
    excerptHtml,
    faqs,
    formattedDate,
    formattedUpdatedDate,
    h1Title,
    imageLookup,
    labels,
    optimizedPostImage,
    postImage,
    relatedCaseStudyCta,
    relatedCaseStudyPath,
    relatedPosts,
    relatedServiceCta,
    relatedServicePath,
    showAiSearchLink,
    tldr,
    urls,
    contactAuditCta,
  } =
    useBlogPostData(props);
  const authorName = props.data.founder?.name || props.data.companyName;
  const resolvedAuthorRole = props.data.founder?.name ? authorRole : "";
  const showUpdatedDate = !!props.updatedDate && props.updatedDate !== props.date;

  return (
    <article className="post-content flex flex-col items-center">
        <nav
          aria-label={labels.breadcrumb}
          className="mb-4 w-full max-w-4xl"
        >
          <ol className="flex flex-wrap items-center justify-center gap-2 text-xs text-secondary sm:justify-start">
            <li>
              <AppLink className="hover:text-light" to="/">
                {labels.home}
              </AppLink>
            </li>
            <li aria-hidden="true">/</li>
            <li>
              <AppLink className="hover:text-light" to="/blog/">
                {labels.blogHub}
              </AppLink>
            </li>
            <li aria-hidden="true">/</li>
            <li aria-current="page" className="text-light/90">
              {h1Title}
            </li>
          </ol>
        </nav>
        <h1 className="text-3xl text-center">{h1Title}</h1>
        <div className="mt-4 flex flex-wrap justify-center gap-2 text-xs text-secondary">
          {currentCategoryLabel ? (
            <span className="rounded-full border border-secondary/30 px-3 py-1">
              {currentCategoryLabel}
            </span>
          ) : null}
          {currentSeriesLabel ? (
            <span className="rounded-full border border-secondary/30 px-3 py-1">
              {currentSeriesLabel}
            </span>
          ) : null}
        </div>
        <div className="mt-3 grid w-full max-w-2xl grid-cols-1 gap-y-1 text-sm text-secondary md:grid-cols-2 md:gap-x-8 md:gap-y-2">
          <span className="text-center sm:text-left">
            {labels.by} {authorName}
            {resolvedAuthorRole ? `, ${resolvedAuthorRole}` : ""}
          </span>
          <span className="text-center sm:text-right">{labels.published} {formattedDate}</span>
          {showUpdatedDate ? <span className="text-center sm:text-left">{labels.updated} {formattedUpdatedDate}</span> : null}
          {props.data.founder?.name ? <span className={`${!showUpdatedDate ? 'text-center sm:text-left' : 'text-center sm:text-right'}`}>{labels.reviewedBy} {props.data.founder.name}</span> : null}
        </div>

        {optimizedPostImage ? (
          <GatsbyImage
            image={optimizedPostImage}
            alt={postImage.alt || h1Title}
            className="mx-auto my-4 max-w-4xl overflow-hidden rounded-2xl"
          />
        ) : postImage?.src ? (
          <img
            className="mx-auto my-4"
            src={postImage.src}
            alt={postImage.alt || h1Title}
            loading="lazy"
            decoding="async"
          />
        ) : null}

        {/* TL;DR */}
        {tldr.length > 0 ? (
          <section className="w-full max-w-3xl my-6">
            <h2 className="text-xl font-semibold mb-2">{labels.tldr}</h2>
            <ul className="list-disc pl-6 space-y-1">
              {tldr.map((item, idx) => (
                <li key={idx}>{item}</li>
              ))}
            </ul>

            <div className="mt-4 flex flex-wrap gap-3">
              <AppLink className="underline" to={urls.seo}>
                SEO
              </AppLink>
              {showAiSearchLink ? (
                <AppLink className="underline" to={urls.aiSearch}>
                  {labels.aiSearch}
                </AppLink>
              ) : null}
              <AppLink className="underline" to={urls.web}>
                {labels.web}
              </AppLink>
              {relatedCaseStudyPath ? (
                <AppLink className="underline" to={relatedCaseStudyPath}>
                  {relatedCaseStudyCta}
                </AppLink>
              ) : null}
              <AppLink className="underline" to={urls.portfolio}>
                Portfolio
              </AppLink>
              <AppLink className="underline" to={urls.contact}>
                {contactAuditCta}
              </AppLink>
            </div>
          </section>
        ) : null}

        {/* Main content */}
        <div dangerouslySetInnerHTML={{ __html: excerptHtml }} />

        {relatedPosts.length > 0 ||
        relatedCaseStudyPath ||
        (relatedServicePath && relatedServicePath !== "/services/") ? (
          <section className="w-full max-w-5xl my-8">
            <h2 className="text-2xl font-semibold text-light">
              {props.data.companyName ? (
                t("blog.related_title", {
                  defaultValue: "Continue this topic cluster",
                })
              ) : null}
            </h2>
            <p className="mt-2 text-sm text-secondary">
              {t("blog.related_subtitle", {
                defaultValue:
                  "Related posts and the most relevant service page for this topic.",
              })}
            </p>
            {relatedPosts.length > 0 ? (
              <div className="mt-6 grid grid-cols-1 gap-4 md:grid-cols-3">
                {relatedPosts.map((relatedPost) => {
                  const relatedImage =
                    images[relatedPost.slug as keyof typeof images] ?? images.bg_workflow;
                  const optimizedRelatedImage = imageLookup.get(relatedPost.slug);

                  return (
                    <article
                      key={relatedPost.slug}
                      className="rounded-2xl border border-black/10 bg-primary/70 p-4 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur"
                    >
                      <AppLink
                        to={`/blog/${relatedPost.slug}/`}
                        onClick={() => {
                          void trackCtaClick({
                            cta_name: `related_post_${relatedPost.slug}`,
                            cta_location: `blog_post_${props.slug}`,
                            destination: `/blog/${relatedPost.slug}/`,
                            destination_type: "internal",
                          });
                        }}
                      >
                        {optimizedRelatedImage ? (
                          <GatsbyImage
                            image={optimizedRelatedImage}
                            alt={relatedImage.alt}
                            className="overflow-hidden rounded-xl"
                          />
                        ) : (
                          <img
                            src={relatedImage.src}
                            alt={relatedImage.alt}
                            className="rounded-xl"
                            loading="lazy"
                            decoding="async"
                          />
                        )}
                        <h3 className="mt-4 text-lg font-semibold text-light/90">
                          {t(`blog.${relatedPost.slug}-title`, {
                            defaultValue: relatedPost.title,
                          })}
                        </h3>
                      </AppLink>
                    </article>
                  );
                })}
              </div>
            ) : null}
            <div className="mt-6 flex flex-wrap gap-3">
              {relatedServicePath && relatedServicePath !== "/services/" ? (
                <AppLink
                  to={relatedServicePath}
                  className="rounded-full bg-secondary px-4 py-2 text-sm text-light"
                  onClick={() => {
                    void trackCtaClick({
                      cta_name: "related_service_from_blog_post",
                      cta_location: `blog_post_${props.slug}`,
                      destination: relatedServicePath,
                      destination_type: "internal",
                    });
                  }}
                >
                  {relatedServiceCta}
                </AppLink>
              ) : null}
              {relatedCaseStudyPath ? (
                <AppLink
                  to={relatedCaseStudyPath}
                  className="rounded-full border border-white/15 bg-white/10 px-4 py-2 text-sm text-light"
                >
                  {relatedCaseStudyCta}
                </AppLink>
              ) : null}
              <AppLink className="rounded-full bg-purplesemilight px-4 py-2 text-sm font-semibold text-dark" to={urls.contact}>
                {contactAuditCta}
              </AppLink>
            </div>
          </section>
        ) : null}

        <EntityTrustPanel
          eyebrow={labels.reviewedBy}
          name={authorName}
          role={resolvedAuthorRole}
          summary={props.data.founder?.name ? authorSummary : props.data.companyName}
          highlights={authorHighlights}
          primaryHref={urls.about}
          primaryLabel={labels.authorCta}
          secondaryHref={urls.portfolio}
          secondaryLabel={t("menu.portfolio", { ns: "index" }) as string}
        />

        {/* FAQs */}
        {faqs.length > 0 ? (
          <section className="w-full max-w-3xl my-8">
            <h2 className="text-2xl font-semibold mb-4">{labels.faq}</h2>
            <div className="space-y-4">
              {faqs.map((item, idx) => (
                <div key={idx}>
                  <h3 className="font-semibold">{item.q}</h3>
                  <p className="mt-1">{item.a}</p>
                </div>
              ))}
            </div>

            <div className="mt-6">
              <AppLink className="underline" to={urls.contact}>
                {contactAuditCta}
              </AppLink>
            </div>
          </section>
        ) : null}
      </article>
  );
};

export default Post;
